INSERT INTO permissions(permission_name,permission_code,module_name,description,status)VALUES('View Parking','society.parking.view','parking','View parking slots, vehicles and allocations','ACTIVE'),('Manage Parking Slots','society.parking.slots_manage','parking','Create and update parking slots','ACTIVE'),('Manage Vehicles','society.parking.vehicles_manage','parking','Register and update member vehicles','ACTIVE'),('Allocate Parking','society.parking.allocate','parking','Allocate and release parking slots','ACTIVE')ON DUPLICATE KEY UPDATE status='ACTIVE';
INSERT INTO role_permissions(role_id,permission_id)SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.role_code IN('SUPER_ADMIN','SOCIETY_ADMIN','CHAIRMAN','SECRETARY')AND p.permission_code LIKE 'society.parking.%' ON DUPLICATE KEY UPDATE permission_id=VALUES(permission_id);
INSERT INTO role_permissions(role_id,permission_id)SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.role_code IN('TREASURER','ACCOUNTANT','SECURITY')AND p.permission_code='society.parking.view' ON DUPLICATE KEY UPDATE permission_id=VALUES(permission_id);
INSERT INTO role_permissions(role_id,permission_id)SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.role_code='RESIDENT' AND p.permission_code IN('society.parking.view','society.parking.vehicles_manage') ON DUPLICATE KEY UPDATE permission_id=VALUES(permission_id);
