CREATE TABLE IF NOT EXISTS parking_slots(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,society_id BIGINT UNSIGNED NOT NULL,slot_number VARCHAR(50) NOT NULL,slot_type ENUM('TWO_WHEELER','FOUR_WHEELER','BICYCLE','OTHER') NOT NULL,location VARCHAR(150) NULL,is_reserved BOOLEAN NOT NULL DEFAULT FALSE,status ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE',created_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_by BIGINT UNSIGNED NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,UNIQUE KEY uk_parking_slot(society_id,slot_number),KEY idx_slots_type(society_id,slot_type,status),CONSTRAINT fk_slot_society FOREIGN KEY(society_id) REFERENCES societies(id) ON DELETE RESTRICT ON UPDATE CASCADE)ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS member_vehicles(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,society_id BIGINT UNSIGNED NOT NULL,flat_id BIGINT UNSIGNED NOT NULL,member_id BIGINT UNSIGNED NULL,vehicle_number VARCHAR(30) NOT NULL,vehicle_type ENUM('CAR','BIKE','SCOOTER','BICYCLE','OTHER') NOT NULL,brand VARCHAR(100) NULL,model VARCHAR(100) NULL,color VARCHAR(50) NULL,status ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE',created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_by BIGINT UNSIGNED NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,UNIQUE KEY uk_vehicle_number(society_id,vehicle_number),KEY idx_vehicle_flat(society_id,flat_id,status),CONSTRAINT fk_vehicle_society FOREIGN KEY(society_id) REFERENCES societies(id) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT fk_vehicle_flat FOREIGN KEY(flat_id) REFERENCES flats(id) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT fk_vehicle_member FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE SET NULL ON UPDATE CASCADE)ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS parking_allocations(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,society_id BIGINT UNSIGNED NOT NULL,slot_id BIGINT UNSIGNED NOT NULL,vehicle_id BIGINT UNSIGNED NOT NULL,flat_id BIGINT UNSIGNED NOT NULL,allocated_from DATE NOT NULL,allocated_to DATE NULL,status ENUM('ACTIVE','ENDED') NOT NULL DEFAULT 'ACTIVE',created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,ended_by BIGINT UNSIGNED NULL,ended_at DATETIME NULL,KEY idx_allocation_active_slot(society_id,slot_id,status),KEY idx_allocation_active_vehicle(society_id,vehicle_id,status),CONSTRAINT fk_allocation_society FOREIGN KEY(society_id) REFERENCES societies(id) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT fk_allocation_slot FOREIGN KEY(slot_id) REFERENCES parking_slots(id) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT fk_allocation_vehicle FOREIGN KEY(vehicle_id) REFERENCES member_vehicles(id) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT fk_allocation_flat FOREIGN KEY(flat_id) REFERENCES flats(id) ON DELETE RESTRICT ON UPDATE CASCADE)ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
